(() => {
    const header = document.querySelector('.js-header');
    if (header) {
        let lastScrollTop = 0;
        window.addEventListener('scroll', () => {
            const current = window.scrollY || 0;
            if (current < lastScrollTop && current > 32) {
                header.classList.add('is-sticky');
            } else {
                header.classList.remove('is-sticky');
            }
            lastScrollTop = current;
        });
    }

    const mobileToggle = document.querySelector('.enterprise-mobile-toggle');
    const navMenu = document.querySelector('.navbar__menu');
    if (mobileToggle && navMenu) {
        mobileToggle.addEventListener('click', () => {
            navMenu.classList.toggle('is-active');
            mobileToggle.classList.toggle('is-active');
        });
    }

    const slider = document.querySelector('.js-hero-slider');
    if (slider) {
        const slides = Array.from(slider.querySelectorAll('.enterprise-hero__slide'));
        const dotContainer = slider.querySelector('.js-hero-dots');
        const prevBtn = slider.querySelector('.js-hero-prev');
        const nextBtn = slider.querySelector('.js-hero-next');
        const pauseBtn = slider.querySelector('.js-hero-pause');
        const currentEl = slider.querySelector('.js-hero-current');
        const autoplay = slider.dataset.autoplay === 'true';
        const interval = Number(slider.dataset.interval || 6000);
        let idx = 0;
        let timer = null;
        let isPaused = false;

        const drawDots = () => {
            if (!dotContainer) return;
            dotContainer.innerHTML = slides.map((_, i) => (
                `<button class="enterprise-dot ${i === idx ? 'is-active' : ''}" data-index="${i}" aria-label="Go to slide ${i + 1}"></button>`
            )).join('');
        };

        const render = () => {
            slides.forEach((slide, i) => {
                slide.classList.toggle('is-active', i === idx);
            });
            drawDots();
            if (currentEl) currentEl.textContent = String(idx + 1);
        };

        const goTo = (next) => {
            idx = (next + slides.length) % slides.length;
            render();
        };

        if (slides.length) {
            render();
            if (dotContainer) {
                dotContainer.addEventListener('click', (event) => {
                    const target = event.target;
                    if (target instanceof HTMLElement && target.dataset.index) {
                        goTo(Number(target.dataset.index));
                    }
                });
            }
            if (prevBtn) prevBtn.addEventListener('click', () => goTo(idx - 1));
            if (nextBtn) nextBtn.addEventListener('click', () => goTo(idx + 1));
            if (autoplay && slides.length > 1) {
                timer = window.setInterval(() => goTo(idx + 1), interval);
                slider.addEventListener('mouseenter', () => window.clearInterval(timer));
                slider.addEventListener('mouseleave', () => {
                    if (!isPaused) timer = window.setInterval(() => goTo(idx + 1), interval);
                });
                if (pauseBtn) {
                    pauseBtn.addEventListener('click', () => {
                        isPaused = !isPaused;
                        if (isPaused) {
                            window.clearInterval(timer);
                            pauseBtn.textContent = '>';
                        } else {
                            timer = window.setInterval(() => goTo(idx + 1), interval);
                            pauseBtn.textContent = '||';
                        }
                    });
                }
            }
        }
    }

    const cookieBanner = document.querySelector('.js-cookie-banner');
    const acceptBtn = document.querySelector('.js-cookie-accept');
    const declineBtn = document.querySelector('.js-cookie-decline');
    const cookieStorageKey = 'siddhast-cookie-consent';
    if (cookieBanner) {
        const hide = (value) => {
            try {
                if (value) localStorage.setItem(cookieStorageKey, value);
            } catch (e) { /* private browsing */ }
            cookieBanner.classList.add('is-hidden');
            cookieBanner.setAttribute('aria-hidden', 'true');
        };
        try {
            if (localStorage.getItem(cookieStorageKey)) {
                hide();
            } else {
                if (acceptBtn) acceptBtn.addEventListener('click', () => hide('accepted'));
                if (declineBtn) declineBtn.addEventListener('click', () => hide('declined'));
            }
        } catch (e) {
            if (acceptBtn) acceptBtn.addEventListener('click', () => hide('accepted'));
            if (declineBtn) declineBtn.addEventListener('click', () => hide('declined'));
        }
    }
})();
